SET REFERENTIAL_INTEGRITY FALSE;
DELETE FROM CHAPTERS;
DELETE FROM NOVELS;
INSERT INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION)
VALUES (1, 'Solo Leveling: Ragnarok', 'Chugong, Daul', '/uploads/cover_solo_leveling.jpg', 'NOVEL', 'Action, Fantasy, System', 4.9, 'ONGOING', 1, 2024, 'Korea', 'Web Novel', 'Shadow Monarch, Hunters, Dungeons, Overpowered, System, Male Lead', TRUE, FALSE, 'In the shadows of the dimensional rift, a new crisis emerges. Sung Suho, the son of the Shadow Monarch Sung Jinwoo, has lived a normal life until the seals separating the dimensions began to crack. Now, the gates reopen, and the shadows call upon their new lord.');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (1, 1, 1.0, 'The Son of the Monarch', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Sung Suho woke up to a ringing sound in his ears. It wasn''t his alarm clock. It was a cold, mechanical voice echoing directly within his mind.</p>
<p><b>[System Alert: The Seals of the Shadow Realm are breaking.]</b></p>
<p>He looked down at his hands, which were faintly glowing with a deep indigo aura. The same dark radiance he had seen in his recurring childhood dreams, where a warrior clad in shadowy armor stood atop a mountain of fallen beasts. He had never imagined that the legendary figure was his own father, nor that the blood pulsing through his veins carried the authority to command death itself.</p>
<p>"What on earth is this?" Suho muttered, getting out of bed. As his bare feet touched the wooden floor, the room suddenly distorted. Dark mist billowed from the floorboards, coalescing into a small, winged ant soldier who immediately knelt with absolute devotion.</p>
<p>"Greetings, young master! We have waited ten thousand cycles for your awakening!"</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (2, 1, 2.0, 'The Shadow Ant''s Request', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Suho stared at the bowing creature in stunned silence. "Did you... just talk to me?"</p>
<p>"Yes, young master! I am an emissary of the Shadow Army, left behind by the Great Monarch to serve as your guide when the dimensional rift stirs once more!" the tiny ant soldier squeaked passionately.</p>
<p>Suho rubbed his temples with a weary sigh. He had an art history midterm exam in two hours. He did not have time to become a sovereign of the dead. "Look, whatever your name is—"</p>
<p>"You may address me as Beru-junior, my lord!"</p>
<p>"Beru-junior, can we reschedule this monarch training? I need to catch the subway." But before the little soldier could answer, a bone-rattling boom rattled the apartment. The windows cracked from an atmospheric shockwave, followed by the terrifying screech of a beast. A blue dimensional gate had materialized right in the center of Seoul.</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (3, 1, 3.0, 'Gate in the Heart of Seoul', 10, TRUE, CURRENT_TIMESTAMP(), '<p>The sky above Gangnam turned into a swirling vortex of cobalt purple. Pedestrians screamed as cars crashed, their tires screeching violently against the asphalt.</p>
<p>From the depths of the rift, colossal shadow panthers with fangs dripping magma leaped onto the pedestrian overpass. Police sirens wailed helplessly against beasts immune to conventional weaponry.</p>
<p>"Sire, the dimensional barrier has fully collapsed!" Beru-junior reported, expanding his miniature wings. "Will you call forth the legion?"</p>
<p>Suho clenched his fists. The blue aura around his knuckles flared into jet-black flames. A single word resonated deep within his soul, instinctively whispered into the chaos:</p>
<p><b style="color: #a855f7; font-size: 1.2rem;">"ARISE."</b></p>');
INSERT INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION)
VALUES (2, 'The Apothecary Diaries', 'Natsu Hyuuga', '/uploads/cover_apothecary_diaries.jpg', 'NOVEL', 'Mystery, Historical, Drama', 4.8, 'COMPLETED', 1, 2023, 'Japan', 'Light Novel', 'Court Politics, Herbalist, Smart Female Lead, Poison, Investigation', TRUE, FALSE, 'Maomao, a young woman trained in herbal medicine, is kidnapped and sold as a lowly maid into the Emperor''s rear palace. Using her sharp intellect and deep knowledge of poisons and cures, she unravels palace conspiracies while attempting to keep a low profile.');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (4, 2, 1.0, 'The Poison in the Powder', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The rear palace was a city of women, teeming with whispered gossip and silk-clad rivalries. But the most recent rumor was grim: the infant heirs of the imperial consorts were withering away from a mysterious affliction.</p>
<p>Maomao scrubbed the courtyard tiles with quiet diligence, her bangs veiling her observant eyes. She knew the truth. It was neither a demonic curse nor an assassin''s concoction. It was white lead—the deadly ingredient inside the costly cosmetic powder favored by high-ranking concubines. Transferred through physical affection, the mineral poisoned the newborns day by day.</p>
<p>Involving oneself in court intrigues was an invitation to an early grave. Yet, when she caught sight of Consort Gyokuyou cradling her fragile, feverish princess, Maomao could not bear the silence. Under cover of twilight, she penned a discreet warning, wrapped it around a branch of azalea, and left it where the imperial guard could not miss it.</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (5, 2, 2.0, 'The Consort''s Banquet', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Her warning had saved the princess''s life, but it also drew the gaze of Jinshi, the celestial eunuch whose striking countenance bewitched women and men alike.</p>
<p>"You are Maomao, aren''t you?" Jinshi inquired, his smile radiating effortless authority as he observed her in the Jade Pavilion. "You recognized the lead poison."</p>
<p>"I merely recognized symptoms I have seen in medicinal texts, my lord," Maomao answered evenly, bowing low. She had deliberately applied freckles with herbal dye to appear unexceptional.</p>
<p>Jinshi gestured toward a porcelain dish filled with shimmering broth. "Consort Gyokuyou requires a trustworthy poison taster. Care to prove your discerning palate?" Maomao''s eyes twinkled with genuine excitement as she took the spoon—sampling venom was, after all, her greatest passion.</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (6, 2, 3.0, 'The Jade Pavilion''s Secret', 15, TRUE, CURRENT_TIMESTAMP(), '<p>The soup tasted subtly of winter mushrooms and dried ginger, with a peculiar tingling note at the tip of the tongue. Maomao closed her eyes in ecstasy.</p>
<p>"Fascinating," she whispered, her lips curling into a serene, blissful smile. "Extract of pufferfish bladder, carefully measured to induce paralysis rather than sudden death. Truly an exquisite choice of toxin."</p>
<p>The guards drew their swords in shock while Lady Gyokuyou gasped. Jinshi leaned closer, his eyes wide with a mixture of wonder and sheer disbelief. "You truly are an odd creature, little apothecary."</p>');
INSERT INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION)
VALUES (3, 'Omniscient Reader''s Viewpoint', 'sing N song', '/uploads/cover_omniscient_reader.jpg', 'NOVEL', 'Action, Fantasy, Sci-Fi', 4.9, 'ONGOING', 1, 2021, 'Korea', 'Web Novel', 'Apocalypse, Constellations, Survival, Dokkaebi, Smart Lead', TRUE, FALSE, 'Kim Dokja was an ordinary contractor whose only pastime was following a forgotten web novel with over three thousand chapters. When the final chapter concludes, the author sends a cryptic text—and reality suddenly transforms into the deadly scenarios of that very novel.');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (7, 3, 1.0, 'Prologue: Epilogue of a Web Novel', 0, TRUE, CURRENT_TIMESTAMP(), '<p>There were three ways to survive in a ruined world. Now, I have forgotten a few, but one thing is certain: the fact that you who are reading this will survive.</p>
<p>I read those final words on my smartphone as the Seoul subway rolled toward Seongsu Station. ''Ways of Survival'' had run for over a decade. In the beginning, thousands read it. By chapter one hundred, only a dozen remained. By chapter three thousand, I was the sole reader left.</p>
<p>A message notification chimed on my phone. It was from the author: <i>''Thank you for staying with my story until the end. As a token of appreciation, the story becomes paid starting at 7:00 PM. Good luck.''</i> The digital clock ticked over to 19:00, and the train ground to an abrupt halt in pitch darkness.</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (8, 3, 2.0, 'Scenario 1: Proof of Value', 0, TRUE, CURRENT_TIMESTAMP(), '<p>A soft blue sphere floated into the train carriage. It cracked open like an egg, revealing a fluffy creature with small horns and glowing crimson eyes—a Dokkaebi.</p>
<p>"Ah, testing, one two three! Can everyone hear me?" the creature cackled, hovering in mid-air. "From this moment forward, the free trial of your mundane human civilization has officially concluded."</p>
<p>Blue hologram windows flashed before every passenger''s eyes:</p>
<p><b>[Main Scenario #1 – Proof of Value]</b><br>
<b>Category:</b> Main<br>
<b>Difficulty:</b> F<br>
<b>Clear Condition:</b> Kill one or more living beings.<br>
<b>Time Limit:</b> 30 minutes<br>
<b>Penalty for Failure:</b> Death</p>
<p>While panic erupted throughout the car, Kim Dokja calmly opened his phone. He knew every rule, every hidden loophole, and every monster of this world.</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (9, 3, 3.0, 'The Protagonist Emerges', 10, TRUE, CURRENT_TIMESTAMP(), '<p>While the passengers began fighting in sheer terror, Dokja noticed the boy sitting beside him holding an insect collection case containing grasshoppers.</p>
<p>"Hey kid," Dokja said gently, offering a chocolate bar. "Can I trade you for one of those bugs?"</p>
<p>Crushing the insect under his shoe, a chime chimed in his ears:</p>
<p><b>[You have slain a living organism.]</b><br>
<b>[You have achieved the clear conditions for Main Scenario #1.]</b><br>
<b>[The Constellation ''Demon-like Judge of Fire'' is astonished by your ingenuity.]</b><br>
<b>[500 Coins have been sponsored.]</b></p>
<p>The apocalyptic game had begun, and Kim Dokja held the complete walkthrough in his hands.</p>');
INSERT INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION)
VALUES (4, 'Frieren: Beyond Journey''s End', 'Kanehito Yamada', '/uploads/cover_frieren.jpg', 'MANGA', 'Fantasy, Adventure, Slice of Life', 4.9, 'ONGOING', 1, 2023, 'Japan', 'Manga', 'Elves, Magic, Journey, Nostalgia, Female Lead', TRUE, FALSE, 'The ten-year quest to fell the Demon King is over. While her human companions celebrate the dawn of an era they will barely outlive, the immortal elf mage Frieren watches time slip away. Spurred by sorrow and longing, she sets forth on a pilgrimage to truly comprehend human hearts.');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (10, 4, 1.0, 'The End of the Quest', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The Era Meteor Shower illuminated the royal capital every half century. For Himmel the Hero, Eisen the Dwarf, and Heiter the Priest, it was a once-in-a-lifetime miracle.</p>
<p>"Fifty years from now, I will take you to a spot with a much grander view," Frieren said casually, gazing at the falling stars with her porcelain-calm expression.</p>
<p>To an elf who had roamed the earth for over a millennium, fifty years was a mere blink. But when she returned half a century later, Himmel was an old man with a cane and silver hair. Shortly after their reunion, Himmel passed away peacefully. At his funeral, tears unexpectedly streamed down Frieren''s cheeks. "I spent ten years traveling with him," she whispered. "Why did I never try to get to know him?"</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (11, 4, 2.0, 'Priest Heiter''s Request', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Years later, Frieren visited Heiter in his secluded countryside home. The once-boisterous holy man was frail, caring for a war orphan named Fern.</p>
<p>"Frieren," Heiter wheezed with a gentle smile, "I ask of you a favor. Decode this grimoire of immortality... and take Fern as your apprentice."</p>
<p>"Immortality does not exist, and apprentices are a burden," Frieren replied bluntly. But Heiter only smiled, knowing her heart was kinder than her words. Over the seasons that followed, Frieren taught Fern the art of mana suppression, finding quiet warmth in the rhythm of daily life.</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (12, 4, 3.0, 'Journey to Aureole', 15, TRUE, CURRENT_TIMESTAMP(), '<p>With Heiter''s passing, Frieren and young Fern embarked north toward Ende—the realm of souls where the Demon King''s castle once stood.</p>
<p>"Mistress Frieren," Fern asked as they walked along a field of blue moon flowers, "why do you collect seemingly useless spells like turning sweet grapes sour?"</p>
<p>Frieren paused, her twintails fluttering in the morning breeze. "Because Himmel once told me that silly spells bring smiles to people''s faces. And that is what a true adventurer does."</p>');
INSERT INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION)
VALUES (5, 'Cyberpunk: Edgerunners', 'Studio Trigger', '/uploads/cover_cyberpunk.jpg', 'COMIC', 'Sci-Fi, Action, Romance', 4.9, 'COMPLETED', 1, 2022, 'Japan', 'Original', 'Night City, Cyberware, Sandevistan, Mercenary, Dystopia', FALSE, FALSE, 'In a chrome-tinted metropolis governed by mega-corporations and cybernetic excess, young David Martinez loses everything in a stray shootout. Implanting a military-grade Sandevistan neural booster, he dives headfirst into the dangerous mercenary underworld of Night City.');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (13, 5, 1.0, 'City of Dreams', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The yellow skyline of Night City loomed over Santo Domingo. David Martinez pulled his cheap school jacket tighter around his shoulders as the metro whirred along the elevated rails.</p>
<p>His mother worked twelve-hour emergency medical shifts so he could attend the Arasaka Academy. But prestige meant nothing to the corporate kids who mocked his outdated uniform. Then came the shootout on the highway—a drive-by that claimed his mother''s life and left David buried in medical bills he could never repay.</p>
<p>Sitting in their desolate apartment, David stared at the heavy metallic spinal implant recovered from his mother''s jacket. A prototype Sandevistan. "If I''m going to drown in this city," David thought, contacting a shady ripperdoc, "I''ll do it at the speed of light."</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (26, 5, 2.0, 'Like a Boy', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Activating the military chrome sent shockwaves of adrenaline racing through David''s neural network. The world slowed to a crawl: falling rain froze into suspended crystals, and bullets hung motionless in the air.</p>
<p>That night on the train, he met Lucy—a netrunner with prism-dyed hair and eyes that reflected the moon. When she tried to swipe shards from Arasaka executives, David intervened with supersonic speed, catching her off-guard.</p>
<p>"You''ve got military chrome in that skinny spine," Lucy whispered, pulling him into her hideout. "Do you have any idea how dangerous that is in Night City?"</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (27, 5, 3.0, 'Smooth Criminal', 20, TRUE, CURRENT_TIMESTAMP(), '<p>Lucy linked their cyberdecks and projected a braindance of the lunar surface. Sitting side by side on virtual moon rock, the suffocating smog of Night City faded away.</p>
<p>"One day, I''m buying a ticket to the moon," Lucy said quietly, looking up at Earth. "No Arasaka, no badges, no chrome fever. Just quiet."</p>
<p>David looked at her earnest expression and made a silent vow. "I''ll take you there, Lucy. Whatever it takes, I won''t let Night City burn you."</p>');
INSERT INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION)
VALUES (6, 'Tower of God', 'SIU', '/uploads/cover_tower_of_god.jpg', 'COMIC', 'Fantasy, Adventure, Action', 4.7, 'ONGOING', 1, 2020, 'Korea', 'Webtoon', 'Tower, Regulars, Shinsu, Male Lead, Mystery', FALSE, FALSE, 'What do you desire? Wealth? Glory? Power? Revenge? Whatever you desire is waiting at the pinnacle of the Tower. Bam, an Irregular youth who only sought to be reunited with his sole companion Rachel, opens the gates to face tests that challenge the gods themselves.');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (14, 6, 1.0, '1F - Headon''s Floor', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Bam fell through the massive stone gate onto a platform surrounded by misty, bottomless waters. A tall creature with a rabbit-like mask and a glowing staff greeted him with an eerie grin.</p>
<p>"Welcome, boy, to the Tower," Headon spoke, his voice echoing with centuries of age. "All who enter desire something great. What is it that drives you?"</p>
<p>"Rachel," Bam replied immediately, his golden eyes filled with desperate conviction. "She entered before me. I want to be where she is."</p>
<p>Headon chuckled softly. "Then you must pass the entrance exam: break the black ball caged inside the Steel Eel''s lair. An Irregular must show strength worthy of climbing."</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (15, 6, 2.0, 'The Steel Eel & The Black March', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Before Bam could step into the steel cage, the arrival of Princess Yuri Zahard changed everything. Intrigued by an Irregular boy who did not tremble before monsters, she lent him the legendary needle: The Black March.</p>
<p>"Ignite it, boy!" Yuri called out from the observation deck.</p>
<p>As the massive armored serpent lunged with maw wide open, Bam thrust the needle forward. Shinsu flared around the blade in violet lightning, shattering the barrier in an explosive burst of pure energy.</p>');
INSERT INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION)
VALUES (7, 'The Beginning After The End', 'TurtleMe', '/uploads/cover_tbate.jpg', 'NOVEL', 'Fantasy, Action, Romance', 4.8, 'ONGOING', 1, 2022, 'USA', 'Web Novel', 'Reincarnation, Magic, Dragons, Mana Core, Academy', FALSE, FALSE, 'King Grey commanded unmatched authority, wealth, and martial prowess in a world ruled by combat. But behind the crown lay profound solitude. Reborn as Arthur Leywin in the magical continent of Dicathen, he resolves to protect his newfound family and forge true bonds.');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (16, 7, 1.0, 'Early Awakening', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Being an infant with the memories of an undefeated sovereign king was an unusual experience. For the first two years of his life in the Ashber countryside, Arthur Leywin spent his time crawling toward the family library and meditating.</p>
<p>In this world, magic was governed by mana particles floating in the atmosphere. By drawing them into his sternum, Arthur gradually coalesced a nascent mana core. At age four, while attempting to compress the ambient mana, an explosive shockwave blew out the walls of his bedroom.</p>
<p>His parents rushed in terrified, only to find their four-year-old toddler sitting amid the debris, his aura radiating clear cerulean light. Arthur had awakened as a mage years before any recorded prodigy in Dicathen''s history.</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (17, 7, 2.0, 'Mana Core Formation', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Rey and Alice Leywin were both accomplished former adventurers, but neither had ever witnessed a child forming a black-stage mana core at kindergarten age.</p>
<p>"He didn''t just awaken, Alice," Rey whispered, his jaw dropped. "His mana channels are as wide as a veteran knight''s!"</p>
<p>Arthur blinked innocently, offering a babyish giggle to defuse their panic. Yet in his heart, he made a solemn vow: <i>''In my past life, I lived for honor and died alone. In this life, I will use every ounce of my power to protect the warmth of this family.''</i></p>');
INSERT INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION)
VALUES (8, 'Lord of the Mysteries', 'Cuttlefish That Loves Diving', '/uploads/cover_lotm.jpg', 'NOVEL', 'Mystery, Fantasy, Sci-Fi', 4.9, 'COMPLETED', 1, 2020, 'China', 'Web Novel', 'Steampunk, Victorian, Eldritch, Tarot Club, Beyonder', TRUE, FALSE, 'Amid the roar of steam engines and Victorian gas lamps, dark occult forces stir in the fog. Zhou Mingrui awakens in the body of Klein Moretti with a bullet hole through his temple. To unravel the mystery of his rebirth and ascend the Beyonder pathways, he founds the legendary Tarot Club.');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (18, 8, 1.0, 'Crimson', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Pain surged through his skull like a white-hot poker. Klein Moretti sat up on a narrow cot in a modest rented room in Tingen City, clutching his temple.</p>
<p>On the wooden desk beside him lay a brass revolver, an ink-stained notebook with missing pages, and a cracked mirror. When he peered into the glass, he was horrified to find a neat, circular bullet wound on his left temple, dried crimson blood caking his dark hair.</p>
<p>And yet, he was breathing. The clock chimed midnight with a solemn metallic chime. As he recited an ancient luck-enhancement ritual in four steps counter-clockwise, the fabric of space sheared open, pulling his consciousness above the gray fog of eternity.</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (19, 8, 2.0, 'The Fool and the Tarot Club', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Above the infinite sea of grayish-white fog stood an ancient divine palace supported by majestic stone pillars. Klein found himself seated at the head of a bronze long table.</p>
<p>With a wave of his hand, two shimmering stars in the crimson cosmos flared, projecting the illusory astral figures of a noble lady and a desperate young sailor.</p>
<p>"Who are you? Is this a secret orthodox ritual?" the lady asked, trembling in awe before the divine sanctuary.</p>
<p>Klein leaned back into the shadows of the high-backed chair, steepling his fingers with enigmatic grace. "You may address me as... The Fool."</p>');
INSERT INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION)
VALUES (9, 'Shadow Slave', 'Guiltythree', '/uploads/cover_shadow_slave.jpg', 'NOVEL', 'Fantasy, Action, Mystery', 4.8, 'ONGOING', 1, 2023, 'International', 'Web Novel', 'Nightmare Spell, Shadows, Forgotten Shore, Treacherous Lead', FALSE, FALSE, 'Growing up as an impoverished street rat in the outskirts of the outskirts, Sunny had zero ambition beyond surviving another winter. But when infected by the Nightmare Spell, he is transported into an ancient fallen realm where monsters roam, unlocking a divine shadow aspect with a treacherous curse.');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (20, 9, 1.0, 'Nightmare Spell', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Sunny had spent his sixteen years of life learning how to be invisible. In the impoverished outskirts of N5, being noticeable got you mugged, beaten, or harvested for organs.</p>
<p>So when the black markings of the Nightmare Spell began spiraling across his collarbone, he didn''t cry or pray. He just sighed and stole two cans of synth-meat from the corner store. If he was going to fall into a comatose trial and die, he might as well die on a full stomach.</p>
<p>That night, reality dissolved into an endless blizzard on a mountain peak. The mechanical whisper of the Spell echoed in his mind: <i>''Aspirant, welcome to your First Nightmare.''</i></p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (21, 9, 2.0, 'The Mountain King', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The wind howled like a pack of wolves, freezing the blood in Sunny''s veins. He was chained to a wooden post inside a sacrificial caravan, surrounded by shivering slaves.</p>
<p>Through the blizzard, two crimson searchlights opened in the crags above. A Mountain King—a colossal centipede-like abomination plated with black ice—descended toward the helpless humans.</p>
<p>Sunny didn''t scream like the others. He carefully slipped his frostbitten thumb out of the iron cuff. "Fools die honorably," Sunny muttered through chattering teeth. "Cowards live to tell the tale."</p>');
INSERT INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION)
VALUES (10, 'Super Cub', 'Tone Koken', '/uploads/cover_super_cub.jpg', 'MANGA', 'Slice of Life', 4.8, 'COMPLETED', 1, 2021, 'Japan', 'Light Novel', 'Motorbikes, School Life, Peaceful, Solitude', FALSE, FALSE, 'Koguma, a quiet second-year high school student in Yamanashi with no parents, friends, or hobbies, buys a pre-owned Honda Super Cub for ten thousand yen. The little motorized scooter quietly expands her horizons, bringing gentle adventures and lifelong companionship.');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (22, 10, 1.0, 'The Pre-owned Super Cub', 0, TRUE, CURRENT_TIMESTAMP(), '/uploads/604f9929-1464-441b-af14-3149ba91a05a.png,/uploads/5843a4ab-08f5-4324-a663-030a28146b3d.png,/uploads/f1bf2da9-b171-47de-9467-6cd93c8205c1.png,/uploads/49dd87d7-6727-4b49-b5e0-7424ffd8e405.png,/uploads/199d78c6-ac19-4b90-a905-6bd1a59ea708.png,/uploads/96131cf8-91f5-41fd-99bc-78f235135bca.png,/uploads/608d5d4e-0f56-4efc-b6ea-6dfaee7aafeb.png,/uploads/dbcf04ee-789a-4ac4-8033-fd7cb874503f.png,/uploads/6a4944a2-d625-475d-beca-105381e1b7ae.png,/uploads/9dd61a36-5ed3-4416-ade4-e62f92ee5a38.png');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (23, 10, 2.0, 'Morning Commute', 0, TRUE, CURRENT_TIMESTAMP(), '<p>The gentle hum of the 50cc four-stroke engine resonated through the morning air of Hokuto. Koguma adjusted her retro helmet, feeling the cool mountain breeze on her cheeks.</p>
<p>For the first time in her life, the monotonous uphill bicycle ride to school was replaced by the smooth glide of two wheels. She stopped at the traffic light, her hands resting comfortably on the black rubber handlebars. When a classmate noticed her at the bike rack, a hesitant smile broke across Koguma''s face—her world was finally starting to grow.</p>');
INSERT INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION)
VALUES (11, 'Chainsaw Man', 'Tatsuki Fujimoto', '/uploads/cover_chainsaw_man.png', 'MANGA', 'Action, Fantasy, Horror', 4.8, 'ONGOING', 1, 2022, 'Japan', 'Manga', 'Devils, Chainsaw, Public Safety, Dark Comedy, Action', FALSE, FALSE, 'Denji lives in squalor, drowning in his deceased father''s debts to the yakuza and hunting devils alongside Pochita, the canine Chainsaw Devil. After a brutal ambush leaves them diced to pieces, Pochita merges into Denji''s heart, awakening the ferocious Chainsaw Man.');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (24, 11, 1.0, 'Dog & Chainsaw', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Denji''s dream was simple: jam on toast, video games with Pochita, and holding hands with a girl before he died. Instead, he lived in a leaky shed eating cigarette butts on a dare for loose change.</p>
<p>Pochita, a dog with a whirring saw blade emerging from his forehead, whimpered affectionately as Denji chopped firewood. "Don''t worry, buddy," Denji smiled weakly, coughing blood. "We''ll pay off this debt someday."</p>
<p>That night, the yakuza boss lured them into an abandoned warehouse under the guise of an extermination job. But the warehouse was a slaughterhouse ruled by the Zombie Devil. Betrayed and hacked to pieces, Denji''s severed hand brushed against Pochita''s wound, sealing their eternal pact.</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (25, 11, 2.0, 'A Place Where Dreams Come True', 0, TRUE, CURRENT_TIMESTAMP(), '<p><i>''Denji... I loved hearing you talk about your dreams,''</i> Pochita''s voice resonated in the void. <i>''In exchange for my heart... show me your dreams.''</i></p>
<p>Denji''s eyes snapped open amid the blood-drenched heaps. A starter cord dangled from the center of his chest. He gripped the handle and pulled back hard.</p>
<p><b>*VVRRRRRRRRRRRRRRRRRRRRRRR!*</b></p>
<p>Twin chainsaws erupted from his forearms, while a vicious armored blade ripped through his skull. The slaughter of the Zombie horde began, heralding the birth of Chainsaw Man.</p>');
INSERT INTO NOVELS (ID, TITLE, AUTHOR, COVER_URL, TYPE, GENRE, RATING, STATUS, CREATOR_ID, RELEASE_YEAR, COUNTRY_OF_ORIGIN, SOURCE, TAGS, EDITOR_SELECTION, HIDDEN, DESCRIPTION)
VALUES (12, 'Spy x Family', 'Tatsuya Endo', '/uploads/cover_spy_x_family.jpg', 'MANGA', 'Comedy, Action, Slice of Life', 4.8, 'COMPLETED', 1, 2021, 'Japan', 'Manga', 'Spy, Telepath, Assassin, Wholesome Family, Comedy', TRUE, FALSE, 'Master spy Twilight must assemble a phony family within seven days to infiltrate an exclusive social gathering at Eden Academy. He adopts Anya, an orphaned telepath, and marries Yor, a soft-spoken city hall clerk who moonlights as the lethal assassin Thorn Princess.');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (28, 12, 1.0, 'Mission 1: Operation Strix', 0, TRUE, CURRENT_TIMESTAMP(), '<p>Agent Twilight had assumed a thousand identities: diplomat, doctor, thief, soldier. But his newest top-secret mission for WISE was unprecedented: get married and enroll a child in Eden Academy within seven days.</p>
<p>At a decrepit orphanage in Ostania, he found Anya—a pink-haired little girl sitting quietly with a crossword puzzle. Unbeknownst to Twilight, Anya was a telepath who had escaped a secret government lab.</p>
<p>Hearing his thoughts—<i>''I need a child who can read and write to pass the admissions test''</i>—Anya swiftly filled out the puzzle by reading his mind. "Anya is very smart!" she declared with wide, sparkly eyes. "Take Anya home!"</p>');
INSERT INTO CHAPTERS (ID, NOVEL_ID, CHAPTER_NUMBER, TITLE, PRICE, PUBLISH_NOTIFICATION_SENT, PUBLISH_AT, CONTENT)
VALUES (29, 12, 2.0, 'Mission 2: Secure a Wife', 0, TRUE, CURRENT_TIMESTAMP(), '<p>With Anya adopted, the second hurdle proved even more daunting: Eden Academy required both parents to attend the formal entrance interview.</p>
<p>At a local tailor shop, Twilight crossed paths with Yor Briar, a graceful twenty-seven-year-old clerk looking for a fake boyfriend to quiet her co-workers'' suspicious questions. Hearing Yor''s secret thoughts—<i>''I must avoid drawing police attention to my assassin work as Thorn Princess''</i>—Anya beamed with utter delight.</p>
<p>"Anya wants a pretty mama!" she chimed in, grabbing both their hands. And thus, the world''s most dangerous and wholesome faux family was born.</p>');
